// Valida o JSON do Calculista; números chegam como número (o banco ainda aceita "R$ 1.234,56").
const lead = $('Leads esperando o Calculista').item.json;
const raw = String($json.output ?? $json.text ?? '').replace(/^```(json)?/, '').replace(/```$/, '').trim();
let data = null, erro = null;
try { data = JSON.parse(raw); } catch (e) { erro = 'JSON inválido: ' + e.message; }
if (data && !Array.isArray(data.verbas)) { erro = 'verbas ausente'; data = null; }
const usage = $json.tokenUsage ?? $json.usage ?? {};
const tokens_in = usage.promptTokens ?? usage.input_tokens ?? null, tokens_out = usage.completionTokens ?? usage.output_tokens ?? null;
const price_in = Number($env.LLM_PRICE_IN_PER_MTOK ?? 3), price_out = Number($env.LLM_PRICE_OUT_PER_MTOK ?? 15);
const cost_usd = (tokens_in != null && tokens_out != null) ? +((tokens_in * price_in + tokens_out * price_out) / 1e6).toFixed(6) : null;
return [{ json: { lead_id: lead.lead_id, ok: !!data, data, erro: erro ?? (data ? null : raw.slice(0, 300)),
                  ai_meta: { agent_role: 'calculo', model: 'claude-sonnet-5', tokens_in, tokens_out, cost_usd } } }];
